INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(94039, 'ruRU', '', '|TInterface\\Icons\\ability_warlock_moltencoregreen.blp:20|tТопор лорда Скверны Закууна начинает испускать |cFFFF0000|Hspell:179622|h[Взрывы Скверны]|h|r!', 24330),
(94040, 'ruRU', '', '|TInterface\\Icons\\inv_axe_2h_pvphorde_a_01blackhigh.blp:20|tЛорд Скверны Закуун снова берёт свой топор, |cFFFF0000|Hspell:179670|h[Вооружаясь]|h|r.', 24330),
(94041, 'ruRU', '', '|TInterface\\Icons\\inv_axe_2h_orgrimmarraid_d_01.blp:20|tЛорд Скверны Закуун впадает в ярость и теперь |cFFFF0000|Hspell:179671|h[Тяжело вооружён]|h|r!', 24330),
(94043, 'ruRU', '', '|TInterface\\Icons\\warrior_talent_icon_mastercleaver.blp:20|tТопор лорда Скверны Закууна испускает |cFFFF0000|Hspell:181498|h[Волны разрушения]|h|r!', 24330),
(94047, 'ruRU', '', 'Скорее, ты должен увидеть это место!', 24330),
(94048, 'ruRU', '', 'Сюда, командир!', 24330),
(94049, 'ruRU', '', 'Отличное место... хорошие сектора обстрела... отличные маршруты разведки. Рекомендую установить здесь твой флаг, командир.', 24330),
(94064, 'ruRU', '', 'Расскажи мне о Зет''Голе.', 24330),
(94067, 'ruRU', '', 'Эта бедная деревня... разгромлена саргереями...', 24330),
(94068, 'ruRU', '', 'Что происходит в Храме Ша''наар?', 24330),
(94071, 'ruRU', '', 'Пеплосерд...', 24330),
(94072, 'ruRU', '', 'Охота продолжается здесь, командир. У меня есть донесения о Дозоре Актара прямо на северо-западе и Крепости Скобяника, том большом тоннеле на юго-востоке.', 24330),
(94073, 'ruRU', '', 'Араккоа в Танаане? Расскажи подробнее о Дозоре Актара.', 24330),
(94074, 'ruRU', '', 'Изгои обеспокоены судьбой своих собратьев. Некоторые заблудшие души проходят обучение у Совета Теней тёмной магии Скверны и призыву демонов. Они даже завербовали нескольких высших араккоа, но та местность значительно опаснее — тебе понадобятся союзники, чтобы зачистить её. Нужно поскорее уничтожить это ядовитое гнездо.', 24330),
(94076, 'ruRU', '', '[Натанос и его следопыты выдвигаются.]', 24330),
(94077, 'ruRU', '', 'Прямо по курсу корабли Альянса! Правим к берегу! Держитесь все, дальше будет только хуже, прежде чем станет лучше!', 24330),
(94079, 'ruRU', '', '[Натанос спрыгивает со скалы и подходит.]', 24330),
(94084, 'ruRU', '', 'Не уверен, бывал ли я когда-нибудь в местности, настолько решительно настроенной меня убить!$b$bТем не менее у меня есть кое-какие первые сведения о гавани Железной Крепости прямо на северо-западе, Кузне Скверны на юго-востоке и Троне Кил''джедена на горе прямо за твоей спиной.', 24330),
(94085, 'ruRU', '', 'В эту гавань заходит много кораблей, что там происходит?', 24330),
(94086, 'ruRU', '', 'Похоже, Железная Орда стягивает сюда все свои отдалённые владения. Большинство солдат Железной Орды высаживаются в гавани и сразу же отправляются на обращение. Остальные остаются и подвозят боеприпасы и прочие ресурсы для снабжения армии.$b$bЕсли Гул''дану позволят обратить всю Железную Орду, у него будет непобедимая армия!', 24330),
(94101, 'ruRU', '', 'Скоро ты сгоришь вместе с остальным Азеротом!', 24330),
(94102, 'ruRU', '', 'Гори!', 24330),
(94103, 'ruRU', '', 'Неостановим!', 24330),
(94104, 'ruRU', '', 'Сокрушить слабых!', 24330),
(94130, 'ruRU', '', 'Мы посадили королеву в шлюпку, но она не захотела сопровождения. Велела нам остаться и сражаться.', 24330),
(94131, 'ruRU', '', 'Моя догадка? Она высадилась где-то выше по побережью и продолжила путь пешком.', 24330),
(94132, 'ruRU', '', '[Тэттерсейл рассказывает вам всё, что знает, и убегает.]', 24330),
(94139, 'ruRU', '', 'Что-то привело фурболгов в неистовство. Насколько я помню, они никогда прежде не нападали такими силами.', 24330),
(94140, 'ruRU', '', 'Сердце друида Когтя никогда не дрогнет. Мы те, кто выстоит.', 24330),
(94141, 'ruRU', '', 'Архидруид Стальной Коготь всё ещё в курганах, вместе с остальными. Нам нужно скорее их спасти.', 24330),
(94142, 'ruRU', '', 'Нужно держаться. Мы переживём их, я знаю это.', 24330),
(94143, 'ruRU', '', 'Ещё один... бой...', 24330),
(94147, 'ruRU', '', 'Что это за место?', 24330),
(94150, 'ruRU', '', 'Должен быть способ.', 24330),
(94152, 'ruRU', '', 'Кровожад сейчас |TInterface\\Icons\\Spell_Shadow_DeathCoil:20|t |cFFFF0404|Hspell:181295|h[Переварит]|h|r вас!', 24330),
(94154, 'ruRU', '', 'Пеплосерд определённо заслужил свою репутацию. Отсюда было слышно, как демоны вопят в агонии.', 24330),
(94155, 'ruRU', '', 'Встретимся снова на Рубеже Иллидари.', 24330),
(94156, 'ruRU', '', 'Ха-ха-ха... похоже, у нас новый претендент. Целую вечность ни одна душа не приближалась к моему трону.', 24330),
(94157, 'ruRU', '', 'Балдир, узнай, чего ищет душа $n. Я так жажду развлечений.', 24330),
(94159, 'ruRU', '', 'Я соберу остальных рыцарей крови и буду ждать твоего зова.', 24330);
